window.NOTES={"version":45,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子通信"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":18,"chapter":7,"section":"7.1","type":"单选","topic":"媒体格式","title":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","trigger":"真题从图像动画能力、常见媒体格式和能否精确恢复原数据考查压缩。","conclusion":"无损压缩保证解码后恢复被编码的数据；它不能修复编码前已经发生的缩放、降色或其他信息损失。判断格式时，还要区分媒体内容、编码方式和容器。","points":["无损是数据可逐位恢复，不是肉眼看着差不多；有损压缩则不能保证还原被编码前的全部数据。","PNG 使用无损压缩；但若保存前已把照片缩小或减少颜色，丢失的信息不会因存成 PNG 而恢复。","GIF 支持多帧动画，使用调色板索引和无损压缩；单个调色板最多 256 色。把高色彩图像转成 GIF 时，降色过程可能先产生损失。","静态 PNG 保存一幅图像；APNG 支持动画，已纳入 W3C PNG 第三版。JPEG 和 MP3 的常见使用方式分别是有损图像编码和有损音频编码。","WAV 是音频容器，常见内容为未压缩 PCM，也可以承载压缩音频；不能把 WAV 一概说成未压缩。","MIDI 保存演奏事件而非录音波形。比较文件大小前，应确认比较的是否是同一种媒体、相同时长或尺寸，以及相同编码条件。"],"boundary":"“无损压缩”只描述编码与解码这一步。GIF 的颜色上限按调色板理解，不应把多帧动画中可能使用的全部颜色都绝对限定为同一组 256 色。","id":"merged-14","sources":[{"year":2020,"q":18,"type":"单选"},{"year":2023,"q":48,"type":"填空"},{"year":2026,"q":23,"type":"多选"},{"year":2021,"q":16,"type":"单选","page":4}],"keys":["2020-18","2023-48","2026-23","2021-16"],"comparison":{"headers":["格式或技术","通常保存什么","判断要点"],"rows":[["PNG / APNG","静态 / 动态位图","无损编码不逆转此前的编辑损失"],["GIF","索引色位图或动画","压缩无损；转为索引色可能降色"],["JPEG / MP3","图像 / 音频","常见方式为有损编码"],["WAV","音频容器内的音频数据","常见 PCM，也能装压缩音频"],["MIDI","音符、力度等演奏事件","不是录音波形"]]},"related":[{"id":"y2024q32","label":"采样、位深、编码与冗余共同决定数字媒体数据量","reason":"用PCM、压缩音频和MIDI的表示方式进一步区分录音波形、演奏事件、编码和容器。"},{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"PNG或GIF采用无损压缩，仍不能消除保存前的缩放、降色损失；像素与位深决定被编码的数据。"},{"id":"y2023q19","label":"矢量图形放大通常不失真，位图由像素构成","reason":"选择图像格式前先区分矢量对象与像素阵列，避免把无损压缩误认为任意放大都不失真。"}],"pointGroups":[{"title":"无损边界与图像格式","indices":[0,1,2,3]},{"title":"音频容器与演奏事件","indices":[4,5]}]},{"q":27,"chapter":7,"section":"7.1","type":"多选","topic":"媒体元素与图像","title":"多媒体元素、数字图像与颜色深度","trigger":"真题从媒体种类、系统构成、压缩和颜色深度对数据量的影响考查多媒体基础。","conclusion":"多媒体包含文本、图形、图像、音频、动画和视频。位图由像素组成；估算未压缩像素数据量时，要分清每通道位深、每像素位数，以及 bit 与 B。","points":["多媒体系统把不同媒体组织在一起，并依靠硬件与软件完成采集、处理、存储和输出；声音等模拟信号需先数字化。","位图的宽×高给出像素总数。若每像素用 b 位，紧密存放的像素数据量为宽×高×b bit，换成 B 还要除以 8。","“8 位”须看指什么：RGB 每通道 8 位时，每像素是 3×8＝24 位；RGBA 每通道 8 位时为 32 位，其中 A 表示透明度。","索引色保存调色板编号。例如每像素 8 位可表示最多 256 个索引；像素区按 8 位计算，调色板另占空间。","像素数与表示方式相同时，增加每像素位数会增加未压缩像素数据量；实际文件还受压缩、文件头、元数据、调色板和行填充等影响。","MP3 是有损音频编码；MP4 是可承载视频、音频等内容的容器，不能仅凭扩展名判断媒体是否无损。","Flash动画属于动画创作与表现形式，不是一种数字视频无损压缩算法；动画内容可以另行导出为视频。"],"boundary":"该公式估算像素区，不直接等于磁盘上的图像文件大小。颜色通道位数描述颜色表示，Alpha 描述透明度；RGBA 的 32 位不能直接说成 2³² 种 RGB 颜色。","id":"y2020q27","sources":[{"year":2020,"q":27,"type":"多选"},{"year":2023,"q":38,"type":"判断"},{"year":2024,"q":3,"type":"单选"},{"year":2024,"q":23,"type":"多选"}],"keys":["2020-27","2023-38","2024-3","2024-23"],"comparison":{"headers":["示例表示方式","每像素位数","100×100 像素的数据量"],"rows":[["8 位灰度","8 bit","10,000 B"],["RGB：每通道 8 位","24 bit","30,000 B"],["RGBA：每通道 8 位","32 bit","40,000 B"],["8 位索引色","8 bit","像素区 10,000 B，另计调色板"]]},"related":[{"id":"merged-3","label":"bit、Byte、像素与存储容量单位","reason":"像素数据量计算要将每像素位数转换为字节，并按题设区分MB与MiB。"},{"id":"y2020q17","label":"RGB与CMYK的适用场景","reason":"RGB通道参与颜色表示，CMYK面向印刷；颜色模型与每通道位深是不同判断维度。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"实际文件还受压缩和容器影响，不能把宽×高×位深的原始像素量直接当作JPEG或PNG文件大小。"}],"pointGroups":[{"title":"辨认媒体、编码与容器","indices":[0,5,6]},{"title":"按像素、通道和位深计算数据量","indices":[1,2,3,4]}]},{"q":38,"chapter":7,"section":"7.1","type":"填空","topic":"视频","title":"帧、帧率与视频连续感","trigger":"题目要求指出视频信息的基本图像单位。","conclusion":"视频由连续图像帧组成，帧是构成视频画面的基本单位。","points":["帧率表示每秒显示的帧数，常用fps。","更高帧率通常让运动更流畅，也会增加原始数据量和处理负担。","视频还受到分辨率、颜色深度、编码方式和码率影响。"],"boundary":"“超过24帧人眼就完全无法区分”不是严格生理定律；不同内容、亮度和显示条件下感知差异仍存在。","id":"y2020q38","sources":[{"year":2020,"q":38,"type":"填空"}],"keys":["2020-38"],"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"先估算一帧的像素数据，再结合帧率与时长理解未压缩视频数据量的增长。"},{"id":"y2023q18","label":"流媒体强调边传输边播放和连续时序","reason":"帧的连续播放需要数据及时到达；流媒体缓冲可解释帧率之外的网络卡顿原因。"}]},{"q":18,"chapter":7,"section":"7.1","type":"单选","topic":"流媒体","title":"流媒体强调边传输边播放和连续时序","trigger":"题目要求辨认不属于流媒体典型特征的属性。","conclusion":"流媒体的核心是边接收边播放，无须等整个文件下载完成；压缩是常用的减小传输量手段，并非流式传输必须具备的条件。","points":["流媒体既可以用于直播，也可以用于点播；“流式”描述传输与播放方式，不等于内容一定在现场实时产生。","播放器通常先积累一段可播放数据作为缓冲，用来吸收网络速度波动；缓冲耗尽而新数据未及时到达时，可能卡顿或暂停等待。","压缩可降低传输所需的数据量，但网络也能传输未压缩音频流，例如 RTP 的 L16 PCM 音频。","是否流式传输、使用何种编码、是否加密，是三个不同问题；机密性需要相应的加密与访问控制，不能由“流媒体”一词推出。","数字文件逐字节正确复制不会自行降低画质或音质；重新使用有损编码转码，才可能再损失信息。"],"boundary":"“可边下边播”不保证任何网络下都不卡顿，也不等于可以立即跳到任意尚未获取的位置；跳转能力还取决于媒体组织、服务器支持和播放器实现。","id":"y2023q18","sources":[{"year":2023,"q":18,"type":"单选"},{"year":2022,"q":18,"type":"单选"}],"keys":["2023-18","2022-18"],"related":[{"id":"y2020q26","label":"带宽、吞吐量、时延与单位","reason":"网络的实际有效速率和波动决定缓冲能否及时补充，标称带宽本身不能保证播放不卡顿。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"流式播放、压缩编码和容器是不同维度；逐字节复制与再次有损转码也应分别判断。"}],"pointGroups":[{"title":"直播、点播与播放缓冲","indices":[0,1]},{"title":"分开判断压缩、加密与复制转码","indices":[2,3,4]}]},{"q":19,"chapter":7,"section":"7.1","type":"单选","topic":"图形图像","title":"矢量图形放大通常不失真，位图由像素构成","trigger":"题目比较计算机图形与数字图像放大后的表现。","conclusion":"矢量图形由数学对象描述，缩放时可重新计算边界；位图由固定像素阵列构成，过度放大会出现锯齿或像素块。","points":["Logo、图标和线稿常适合矢量表示。","照片和连续色调画面通常适合位图表示。","矢量图最终显示到屏幕或打印时仍要栅格化输出。"],"boundary":"矢量并非任何情况下文件都更小，也不是所有“绘制出来的图”都自动属于矢量图。","id":"y2023q19","sources":[{"year":2023,"q":19,"type":"单选"}],"keys":["2023-19"],"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"位图放大受固定像素阵列约束，可进一步从像素数和每像素位数理解图像表示。"},{"id":"y2024q43","label":"锐化增强边缘和局部细节","reason":"位图放大或缺少细节后，锐化只能增强边缘清晰感，不能把缺失像素信息变回来。"}]},{"q":28,"chapter":7,"section":"7.1","type":"多选","topic":"数字媒体数据量","title":"采样、位深、编码与冗余共同决定数字媒体数据量","trigger":"真题综合考查音频采样率、MIDI与波形、JPEG有损压缩及图像空间冗余。","conclusion":"未压缩 PCM 音频的数据量由采样率、量化位数、声道数和时长共同决定；采样率管每秒采多少次，量化位数管每次样值用多少位表示。","points":["采样率的单位是 Hz，表示每个声道每秒的采样次数；量化位数表示每个样值所用的位数。二者描述不同环节。","PCM 码率＝采样率×量化位数×声道数，单位为 bit/s；PCM 数据量＝码率×秒数÷8，单位为 B。","44.1 kHz、16 位、单声道、120 秒的 PCM 数据量是 44,100×16×1×120÷8＝10,584,000 B；改成双声道则为 21,168,000 B，均未计文件头。","压缩音频若已知平均码率，可按平均码率×时长÷8 估算编码数据量；不能把 PCM 公式直接当作 MP3 等压缩文件的大小公式。","MIDI 主要记录音符、力度、音色选择等演奏事件，不直接保存录制的声音波形；同一 MIDI 用不同音源播放，声音可能不同。","压缩可利用数据冗余；有损压缩还可能舍弃部分感知信息。图像相邻像素的相似属于空间冗余，JPEG 通常采用有损压缩。"],"boundary":"单独提高采样率不保证听起来更好，音质还受信号来源、量化、编码和播放设备影响。数据量的倍数关系须固定其他条件；kHz 中的 k 按 1000 计算，B 与 bit 相差 8 倍。","id":"y2024q32","sources":[{"year":2023,"q":28,"type":"多选"},{"year":2024,"q":32,"type":"判断"},{"year":2022,"q":17,"type":"单选"},{"year":2022,"q":38,"type":"判断"},{"year":2021,"q":38,"type":"填空","page":6}],"keys":["2023-28","2024-32","2022-17","2022-38","2021-38"],"comparison":{"headers":["量","说明","常用单位"],"rows":[["采样率","每声道每秒采样多少次","Hz、kHz"],["量化位数","每个样值用多少位表示","bit/样值"],["声道数","同时记录多少路声音","单声道 1、双声道 2"],["PCM 码率","采样率×量化位数×声道数","bit/s"],["压缩音频平均码率","编码后平均每秒的数据位数","bit/s、kbit/s"]]},"related":[{"id":"merged-3","label":"bit、Byte、像素与存储容量单位","reason":"采样率乘位深和声道数得到bit/s，乘时长后还要除以8才能换成B。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"PCM原始数据公式、MP3平均码率估算和WAV容器判断必须分别使用，MIDI也不是录音波形。"},{"id":"y2020q26","label":"带宽、吞吐量、时延与单位","reason":"算出音频码率和数据量后，可将其作为网络传输计算的输入，同时区分媒体码率与链路有效速率。"}],"pointGroups":[{"title":"采样参数、PCM与压缩码率计算","indices":[0,1,2,3]},{"title":"演奏事件与压缩冗余","indices":[4,5]}]},{"q":4,"chapter":7,"section":"7.1","type":"单选","topic":"多媒体特征","title":"多媒体强调集成、交互与实时处理","trigger":"题目要求从若干描述中找出不属于多媒体技术特征的一项。","conclusion":"多媒体技术通常具有多样性、集成性、交互性和实时性，“单一性”与其核心含义相反。","points":["多样性指文本、图形、图像、音频、动画和视频等媒体。","集成性指多种媒体及软硬件协同处理。","交互性允许用户影响内容呈现和系统反馈。","音视频连续播放和及时响应用户动作强调实时性；多种媒体存在强调多样性/集成性，操作能改变反馈强调交互性。","文字同样属于多媒体元素；远程医疗、教学网页等可综合文本、图像、声音和视频，但不是所有网页都必定同时包含全部媒体类型。"],"boundary":"并非每个多媒体作品都具备相同程度的实时性或交互性，教材概括描述的是技术特征。","id":"y2026q4","sources":[{"year":2026,"q":4,"type":"单选"},{"year":2022,"q":49,"type":"填空"},{"year":2021,"q":17,"type":"单选","page":4}],"keys":["2026-4","2022-49","2021-17"],"related":[{"id":"merged-18","label":"虚拟现实的核心特征与判断边界","reason":"VR把多感知、交互与实时反馈组合起来，但普通多媒体或3D画面不因此自动成为VR。"},{"id":"y2020q38","label":"帧、帧率与视频连续感","reason":"连续音视频体现实时性；帧与帧率笔记提供区分连续播放要求和媒体种类多少的实例。"}],"pointGroups":[{"title":"媒体种类与系统集成","indices":[0,1,4]},{"title":"交互反馈与连续时序","indices":[2,3]}]},{"q":17,"chapter":7,"section":"7.3","type":"单选","topic":"颜色模式","title":"RGB与CMYK的适用场景","trigger":"题目询问新建图像文档常见的默认颜色模式。","conclusion":"面向屏幕显示的新建图像通常使用RGB；印刷工作常使用CMYK。","points":["RGB是红、绿、蓝三种光的加色模型。","CMYK是青、品红、黄、黑的印刷减色模型。","灰度模式只记录亮度层次，不保存完整彩色信息。"],"boundary":"软件默认值可能随预设和用途变化，不能把“永远默认RGB”当绝对规则；应结合屏幕或印刷目的。","id":"y2020q17","sources":[{"year":2020,"q":17,"type":"单选"}],"keys":["2020-17"],"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"RGB的三个颜色通道与Alpha透明度通道要分开理解，不能把RGBA的32位全部说成RGB颜色数。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"颜色表示可能在保存前发生转换或降色；之后采用无损压缩也不会恢复此前丢失的信息。"}]},{"q":43,"chapter":7,"section":"7.3","type":"填空","topic":"图像处理","title":"锐化增强边缘和局部细节","trigger":"题目要求填写使模糊图像边缘更清晰的常见处理。","conclusion":"锐化通过增强高频成分或边缘对比，使轮廓和局部细节更突出。","points":["锐化不能真正恢复从未记录下来的细节。","过度锐化会放大噪声并产生光晕。","模糊通常抑制高频成分，适合降噪或柔化。"],"boundary":"锐化改善视觉清晰感，不等于提高原始分辨率；严重失焦或运动模糊需要更复杂的复原方法。","id":"y2024q43","sources":[{"year":2024,"q":43,"type":"填空"}],"keys":["2024-43"],"related":[{"id":"y2023q19","label":"矢量图形放大通常不失真，位图由像素构成","reason":"矢量缩放可重新计算边界，位图锐化则处理已有像素，二者改善清晰程度的机制不同。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"增强视觉清晰感不等于恢复原始数据，可与无损压缩只保证编码阶段可逆的边界对照。"}]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
window.NOTE_REFERENCES={"merged-14":[["W3C PNG 第三版：无损、源图像与参考图像、动画","https://www.w3.org/TR/png-3/"],["MDN：图像格式比较","https://developer.mozilla.org/en-US/docs/Web/Media/Guides/Formats/Image_types"],["MDN：数字音频概念","https://developer.mozilla.org/en-US/docs/Web/Media/Guides/Formats/Audio_concepts"],["MIDI Association：MIDI 概览","https://midi.org/about-midi-part-1overview"]],"y2020q27":[["W3C PNG 第三版：样值、像素、位深与颜色类型","https://www.w3.org/TR/png-3/"],["MDN：图像文件类型与格式指南","https://developer.mozilla.org/en-US/docs/Web/Media/Guides/Formats/Image_types"]],"y2023q18":[["IETF RFC 3551 §4.5.11：RTP 的 L16 未压缩音频","https://www.rfc-editor.org/rfc/rfc3551.html#section-4.5.11"],["MDN：媒体缓冲、跳转与时间范围","https://developer.mozilla.org/en-US/docs/Web/Media/Guides/Audio_and_video_delivery/buffering_seeking_time_ranges"]],"y2024q32":[["MDN：数字音频概念","https://developer.mozilla.org/en-US/docs/Web/Media/Guides/Formats/Audio_concepts"],["MIDI Association：MIDI 概览","https://midi.org/about-midi-part-1overview"],["MIDI Association：MIDI 1.0 消息摘要","https://midi.org/summary-of-midi-1-0-messages"]]};
window.NOTE_DEMOS={"y2020q27":{"kind":"explore","title":"内容还是载体？","task":"点击对象，观察它属于媒体元素还是存储设备。","initial":"媒体元素是信息表现形式，载体负责保存它们。","actions":[{"label":"文字、图像、声音","stage":"媒体元素","result":"直接承担信息表达。","tone":"good"},{"label":"动画、视频","stage":"媒体元素","result":"由连续画面、声音等组织形成。","tone":"good"},{"label":"硬盘、U盘","stage":"存储载体","result":"能保存媒体文件，但自身不是媒体元素。","tone":"warn"}]},"y2020q38":{"kind":"explore","title":"改变视频参数看后果","task":"点击参数变化，观察流畅度与数据量。","initial":"视频由连续的图像帧组成。","actions":[{"label":"帧率24→60 fps","stage":"运动通常更流畅｜原始数据量增加","result":"fps表示每秒显示帧数。","tone":"good"},{"label":"分辨率1080p→4K","stage":"细节增加｜每帧像素增多","result":"它改变空间精细度，不等于帧率。","tone":"good"},{"label":"降低码率","stage":"文件变小｜压缩损失可能增加","result":"码率影响压缩后单位时间的数据量。","tone":"warn"}]},"y2023q18":{"kind":"explore","title":"拖动播放头观察流媒体缓冲区","task":"选择网络状态，观察下载位置、播放位置和缓冲区怎样共同决定卡顿。","initial":"流媒体可以边传边播，不必等完整文件下载。","actions":[{"label":"带宽高于码率","stage":"缓冲逐渐增加","result":"播放稳定并能抵御短时抖动。","tone":"good"},{"label":"带宽短时下降","stage":"消耗缓冲","result":"缓冲尚未耗尽时仍可连续播放。","tone":"warn"},{"label":"缓冲归零","stage":"播放卡顿","result":"播放头追上下载位置。","tone":"bad"},{"label":"开启传输加密","stage":"获得机密性","result":"这是安全措施，不是流媒体的定义特征。","tone":"warn"}]},"y2026q4":{"kind":"explore","title":"观察多媒体的四个特征","task":"点击系统行为，判断它体现哪种特征。","initial":"多媒体把多种数字媒体组织为统一体验。","actions":[{"label":"文字＋声音＋视频同屏","stage":"集成性与多样性","result":"多种媒体被统一处理和呈现。","tone":"good"},{"label":"用户点击改变内容","stage":"交互性","result":"用户行为会影响系统反馈。","tone":"good"},{"label":"视频会议即时响应","stage":"实时性","result":"采集、传输和处理需要及时完成。","tone":"good"},{"label":"只允许单一信息形式","stage":"单一性","result":"与多媒体核心含义相反。","tone":"bad"}]},"y2020q17":{"kind":"explore","title":"屏幕与印刷切换颜色模式","task":"点击输出目的，观察应优先使用RGB还是CMYK。","initial":"颜色模式要跟最终输出介质匹配。","actions":[{"label":"手机和显示器","stage":"RGB","result":"通过红、绿、蓝光的加色混合显示颜色。","tone":"good"},{"label":"四色印刷","stage":"CMYK","result":"使用青、品红、黄、黑油墨的减色体系。","tone":"good"},{"label":"RGB直接印刷","stage":"颜色可能发生偏差","result":"屏幕发光色域与油墨呈色范围不同。","tone":"warn"}]},"y2024q43":{"kind":"explore","title":"拉动锐化强度，看边缘与噪声一起变化","task":"选择处理强度，对比边缘、纹理和光晕。","initial":"原图略显柔和，但噪声较低。","actions":[{"label":"0% 原图","stage":"边缘自然","result":"没有额外高频增强。","tone":"good"},{"label":"35% 适度锐化","stage":"轮廓更清晰","result":"细节感增强且光晕不明显。","tone":"good"},{"label":"90% 过度锐化","stage":"噪声与白边明显","result":"清晰感开始变成伪影。","tone":"bad"},{"label":"锐化=提高分辨率","stage":"错误","result":"无法创造原图未记录的真实细节。","tone":"bad"}]}};
window.NOTE_NAVIGATION={"merged-14":{"related":[{"id":"y2024q32","label":"采样、位深、编码与冗余共同决定数字媒体数据量","reason":"用PCM、压缩音频和MIDI的表示方式进一步区分录音波形、演奏事件、编码和容器。","chapter":7},{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"PNG或GIF采用无损压缩，仍不能消除保存前的缩放、降色损失；像素与位深决定被编码的数据。","chapter":7},{"id":"y2023q19","label":"矢量图形放大通常不失真，位图由像素构成","reason":"选择图像格式前先区分矢量对象与像素阵列，避免把无损压缩误认为任意放大都不失真。","chapter":7}],"topics":[{"id":"cmp-media-representation-size","title":"表示与容量：字符、字形、像素、编码和容器"}]},"y2020q27":{"related":[{"id":"merged-3","label":"bit、Byte、像素与存储容量单位","reason":"像素数据量计算要将每像素位数转换为字节，并按题设区分MB与MiB。","chapter":1},{"id":"y2020q17","label":"RGB与CMYK的适用场景","reason":"RGB通道参与颜色表示，CMYK面向印刷；颜色模型与每通道位深是不同判断维度。","chapter":7},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"实际文件还受压缩和容器影响，不能把宽×高×位深的原始像素量直接当作JPEG或PNG文件大小。","chapter":7}],"topics":[]},"y2020q38":{"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"先估算一帧的像素数据，再结合帧率与时长理解未压缩视频数据量的增长。","chapter":7},{"id":"y2023q18","label":"流媒体强调边传输边播放和连续时序","reason":"帧的连续播放需要数据及时到达；流媒体缓冲可解释帧率之外的网络卡顿原因。","chapter":7}],"topics":[]},"y2023q18":{"related":[{"id":"y2020q26","label":"带宽、吞吐量、时延与单位","reason":"网络的实际有效速率和波动决定缓冲能否及时补充，标称带宽本身不能保证播放不卡顿。","chapter":6},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"流式播放、压缩编码和容器是不同维度；逐字节复制与再次有损转码也应分别判断。","chapter":7}],"topics":[]},"y2023q19":{"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"位图放大受固定像素阵列约束，可进一步从像素数和每像素位数理解图像表示。","chapter":7},{"id":"y2024q43","label":"锐化增强边缘和局部细节","reason":"位图放大或缺少细节后，锐化只能增强边缘清晰感，不能把缺失像素信息变回来。","chapter":7}],"topics":[{"id":"cmp-media-representation-size","title":"表示与容量：字符、字形、像素、编码和容器"}]},"y2024q32":{"related":[{"id":"merged-3","label":"bit、Byte、像素与存储容量单位","reason":"采样率乘位深和声道数得到bit/s，乘时长后还要除以8才能换成B。","chapter":1},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"PCM原始数据公式、MP3平均码率估算和WAV容器判断必须分别使用，MIDI也不是录音波形。","chapter":7},{"id":"y2020q26","label":"带宽、吞吐量、时延与单位","reason":"算出音频码率和数据量后，可将其作为网络传输计算的输入，同时区分媒体码率与链路有效速率。","chapter":6}],"topics":[{"id":"cmp-media-representation-size","title":"表示与容量：字符、字形、像素、编码和容器"}]},"y2026q4":{"related":[{"id":"merged-18","label":"虚拟现实的核心特征与判断边界","reason":"VR把多感知、交互与实时反馈组合起来，但普通多媒体或3D画面不因此自动成为VR。","chapter":9},{"id":"y2020q38","label":"帧、帧率与视频连续感","reason":"连续音视频体现实时性；帧与帧率笔记提供区分连续播放要求和媒体种类多少的实例。","chapter":7}],"topics":[]},"y2020q17":{"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"RGB的三个颜色通道与Alpha透明度通道要分开理解，不能把RGBA的32位全部说成RGB颜色数。","chapter":7},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"颜色表示可能在保存前发生转换或降色；之后采用无损压缩也不会恢复此前丢失的信息。","chapter":7}],"topics":[]},"y2024q43":{"related":[{"id":"y2023q19","label":"矢量图形放大通常不失真，位图由像素构成","reason":"矢量缩放可重新计算边界，位图锐化则处理已有像素，二者改善清晰程度的机制不同。","chapter":7},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"增强视觉清晰感不等于恢复原始数据，可与无损压缩只保证编码阶段可逆的边界对照。","chapter":7}],"topics":[]}};
